-- As 4 imagens em todas as faixas: 4-6 de Davi, Levi, Marta e Perfume ganha o quadro que faltava; o dilema do 11-13 passa a ter uma imagem por momento (images). Só mexe na história (story). Publicar o app e a API ANTES de rodar.
\set ON_ERROR_STOP on
BEGIN;
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM devotional_kids WHERE devotional_id IN ('cmvue6llj000koe2lqtw0xdz2','cmvv1whpq0002pm2l3f1bfo13','cmvyv3ozp003ho72lezbf5h9r','cmvyun7rw0032o72lmlzc68bk') AND band = '4-6' AND language IN ('pt-BR','en','es','fr','it') AND jsonb_array_length(story->'panels') = 3;
  IF n <> 20 THEN RAISE EXCEPTION 'esperava 20 versoes 4-6 com 3 quadros e encontrei %', n; END IF;
  SELECT count(*) INTO n FROM devotional_kids WHERE devotional_id IN ('cmvudrag10002oe2ldyzmvhaa','cmvue6llj000koe2lqtw0xdz2','cmvv1whpq0002pm2l3f1bfo13','cmvyun7rw0032o72lmlzc68bk','cmvyv3ozp003ho72lezbf5h9r') AND band = '11-13' AND language IN ('pt-BR','en','es','fr','it') AND story->>'format' = 'dilemma' AND NOT (story ? 'images');
  IF n <> 25 THEN RAISE EXCEPTION 'esperava 25 dilemas sem images e encontrei %', n; END IF;
END $$;
UPDATE devotional_kids SET story = jsonb_set(story, '{panels}', '[{"image": "/ilustracoes/davi-e-a-arca/quadros/faixa-4-6-1.webp", "speech": "Deus está com a gente!", "caption": "Davi levou a arca de Deus para Jerusalém."}, {"image": "/ilustracoes/davi-e-a-arca/quadros/faixa-4-6-2.webp", "caption": "Davi agradeceu a Deus com as mãos para o alto.", "speech": "Obrigado, Senhor!"}, {"image": "/ilustracoes/davi-e-a-arca/quadros/faixa-4-6-3.webp", "speech": "Viva o Senhor!", "caption": "O povo tocava trombetas e gritava de alegria."}, {"image": "/ilustracoes/davi-e-a-arca/quadros/faixa-4-6-4.webp", "speech": "Minha alegria é estar com Deus!", "caption": "Davi dançou com todas as suas forças, mesmo sendo rei."}]'::jsonb), updated_at = now() WHERE devotional_id = 'cmvue6llj000koe2lqtw0xdz2' AND band = '4-6' AND language = 'pt-BR' AND jsonb_array_length(story->'panels') = 3;
UPDATE devotional_kids SET story = jsonb_set(story, '{panels}', '[{"image": "/ilustracoes/davi-e-a-arca/quadros/faixa-4-6-1.webp", "speech": "God is with us!", "caption": "David took God''s ark to Jerusalem."}, {"image": "/ilustracoes/davi-e-a-arca/quadros/faixa-4-6-2.webp", "caption": "David thanked God with his hands lifted up.", "speech": "Thank you, Lord!"}, {"image": "/ilustracoes/davi-e-a-arca/quadros/faixa-4-6-3.webp", "speech": "Hooray for the Lord!", "caption": "The people played trumpets and shouted for joy."}, {"image": "/ilustracoes/davi-e-a-arca/quadros/faixa-4-6-4.webp", "speech": "My joy is being with God!", "caption": "David danced with all his strength, even though he was king."}]'::jsonb), updated_at = now() WHERE devotional_id = 'cmvue6llj000koe2lqtw0xdz2' AND band = '4-6' AND language = 'en' AND jsonb_array_length(story->'panels') = 3;
UPDATE devotional_kids SET story = jsonb_set(story, '{panels}', '[{"image": "/ilustracoes/davi-e-a-arca/quadros/faixa-4-6-1.webp", "speech": "¡Dios está con nosotros!", "caption": "David llevó el arca de Dios a Jerusalén."}, {"image": "/ilustracoes/davi-e-a-arca/quadros/faixa-4-6-2.webp", "caption": "David dio gracias a Dios con las manos en alto.", "speech": "¡Gracias, Señor!"}, {"image": "/ilustracoes/davi-e-a-arca/quadros/faixa-4-6-3.webp", "speech": "¡Viva el Señor!", "caption": "El pueblo tocaba trompetas y gritaba de alegría."}, {"image": "/ilustracoes/davi-e-a-arca/quadros/faixa-4-6-4.webp", "speech": "¡Mi alegría es estar con Dios!", "caption": "David bailó con todas sus fuerzas, aunque era rey."}]'::jsonb), updated_at = now() WHERE devotional_id = 'cmvue6llj000koe2lqtw0xdz2' AND band = '4-6' AND language = 'es' AND jsonb_array_length(story->'panels') = 3;
UPDATE devotional_kids SET story = jsonb_set(story, '{panels}', '[{"image": "/ilustracoes/davi-e-a-arca/quadros/faixa-4-6-1.webp", "speech": "Dieu est avec nous !", "caption": "David a emporté l''arche de Dieu à Jérusalem."}, {"image": "/ilustracoes/davi-e-a-arca/quadros/faixa-4-6-2.webp", "caption": "David remercia Dieu, les mains levées.", "speech": "Merci, Seigneur !"}, {"image": "/ilustracoes/davi-e-a-arca/quadros/faixa-4-6-3.webp", "speech": "Vive le Seigneur !", "caption": "Le peuple jouait de la trompette et criait de joie."}, {"image": "/ilustracoes/davi-e-a-arca/quadros/faixa-4-6-4.webp", "speech": "Ma joie, c''est d''être avec Dieu !", "caption": "David a dansé de toutes ses forces, même s''il était roi."}]'::jsonb), updated_at = now() WHERE devotional_id = 'cmvue6llj000koe2lqtw0xdz2' AND band = '4-6' AND language = 'fr' AND jsonb_array_length(story->'panels') = 3;
UPDATE devotional_kids SET story = jsonb_set(story, '{panels}', '[{"image": "/ilustracoes/davi-e-a-arca/quadros/faixa-4-6-1.webp", "speech": "Dio è con noi!", "caption": "Davide portò l''arca di Dio a Gerusalemme."}, {"image": "/ilustracoes/davi-e-a-arca/quadros/faixa-4-6-2.webp", "caption": "Davide ringraziò Dio con le mani alzate.", "speech": "Grazie, Signore!"}, {"image": "/ilustracoes/davi-e-a-arca/quadros/faixa-4-6-3.webp", "speech": "Viva il Signore!", "caption": "Il popolo suonava le trombe e gridava di gioia."}, {"image": "/ilustracoes/davi-e-a-arca/quadros/faixa-4-6-4.webp", "speech": "La mia gioia è stare con Dio!", "caption": "Davide danzò con tutte le sue forze, anche se era re."}]'::jsonb), updated_at = now() WHERE devotional_id = 'cmvue6llj000koe2lqtw0xdz2' AND band = '4-6' AND language = 'it' AND jsonb_array_length(story->'panels') = 3;
UPDATE devotional_kids SET story = jsonb_set(story, '{panels}', '[{"image": "/ilustracoes/levi-e-o-banquete/quadros/faixa-4-6-1.webp", "speech": "Siga-me!", "caption": "Levi trabalhava cobrando impostos. Jesus o chamou, e Levi foi com ele."}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/faixa-4-6-2.webp", "caption": "Levi deixou tudo e foi com Jesus.", "speech": "Eu vou!"}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/faixa-4-6-3.webp", "speech": "Venham comer com a gente!", "caption": "Levi fez uma grande refeição e convidou muita gente para comer com Jesus."}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/faixa-4-6-4.webp", "speech": "Os doentes precisam de médico.", "caption": "Alguns religiosos reclamaram. Jesus explicou que veio chamar quem precisa de ajuda."}]'::jsonb), updated_at = now() WHERE devotional_id = 'cmvv1whpq0002pm2l3f1bfo13' AND band = '4-6' AND language = 'pt-BR' AND jsonb_array_length(story->'panels') = 3;
UPDATE devotional_kids SET story = jsonb_set(story, '{panels}', '[{"image": "/ilustracoes/levi-e-o-banquete/quadros/faixa-4-6-1.webp", "speech": "Follow me!", "caption": "Levi worked collecting taxes. Jesus called him, and Levi went with him."}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/faixa-4-6-2.webp", "caption": "Levi left everything and went with Jesus.", "speech": "I''m coming!"}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/faixa-4-6-3.webp", "speech": "Come and eat with us!", "caption": "Levi prepared a big meal and invited many people to eat with Jesus."}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/faixa-4-6-4.webp", "speech": "The sick need a doctor.", "caption": "Some religious leaders complained. Jesus explained that he came to call those who need help."}]'::jsonb), updated_at = now() WHERE devotional_id = 'cmvv1whpq0002pm2l3f1bfo13' AND band = '4-6' AND language = 'en' AND jsonb_array_length(story->'panels') = 3;
UPDATE devotional_kids SET story = jsonb_set(story, '{panels}', '[{"image": "/ilustracoes/levi-e-o-banquete/quadros/faixa-4-6-1.webp", "speech": "¡Sígueme!", "caption": "Leví trabajaba cobrando impuestos. Jesús lo llamó, y Leví fue con él."}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/faixa-4-6-2.webp", "caption": "Leví lo dejó todo y fue con Jesús.", "speech": "¡Voy!"}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/faixa-4-6-3.webp", "speech": "¡Vengan a comer con nosotros!", "caption": "Leví preparó una gran comida e invitó a mucha gente a comer con Jesús."}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/faixa-4-6-4.webp", "speech": "Los enfermos necesitan médico.", "caption": "Algunos religiosos se quejaron. Jesús explicó que vino a llamar a quienes necesitan ayuda."}]'::jsonb), updated_at = now() WHERE devotional_id = 'cmvv1whpq0002pm2l3f1bfo13' AND band = '4-6' AND language = 'es' AND jsonb_array_length(story->'panels') = 3;
UPDATE devotional_kids SET story = jsonb_set(story, '{panels}', '[{"image": "/ilustracoes/levi-e-o-banquete/quadros/faixa-4-6-1.webp", "speech": "Suis-moi !", "caption": "Lévi travaillait à percevoir les impôts. Jésus l''a appelé, et Lévi l''a suivi."}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/faixa-4-6-2.webp", "caption": "Lévi a tout laissé et a suivi Jésus.", "speech": "J''arrive !"}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/faixa-4-6-3.webp", "speech": "Venez manger avec nous !", "caption": "Lévi a préparé un grand repas et invité beaucoup de monde à manger avec Jésus."}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/faixa-4-6-4.webp", "speech": "Ce sont les malades qui ont besoin de médecin.", "caption": "Des religieux se sont plaints. Jésus a expliqué qu''il est venu appeler ceux qui ont besoin d''aide."}]'::jsonb), updated_at = now() WHERE devotional_id = 'cmvv1whpq0002pm2l3f1bfo13' AND band = '4-6' AND language = 'fr' AND jsonb_array_length(story->'panels') = 3;
UPDATE devotional_kids SET story = jsonb_set(story, '{panels}', '[{"image": "/ilustracoes/levi-e-o-banquete/quadros/faixa-4-6-1.webp", "speech": "Seguimi!", "caption": "Levi faceva l''esattore delle tasse. Gesù lo chiamò e Levi andò con lui."}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/faixa-4-6-2.webp", "caption": "Levi lasciò tutto e andò con Gesù.", "speech": "Vengo!"}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/faixa-4-6-3.webp", "speech": "Venite a mangiare con noi!", "caption": "Levi preparò un grande pranzo e invitò molta gente a mangiare con Gesù."}, {"image": "/ilustracoes/levi-e-o-banquete/quadros/faixa-4-6-4.webp", "speech": "I malati hanno bisogno del medico.", "caption": "Alcuni religiosi si lamentarono. Gesù spiegò che era venuto a chiamare chi ha bisogno di aiuto."}]'::jsonb), updated_at = now() WHERE devotional_id = 'cmvv1whpq0002pm2l3f1bfo13' AND band = '4-6' AND language = 'it' AND jsonb_array_length(story->'panels') = 3;
UPDATE devotional_kids SET story = jsonb_set(story, '{panels}', '[{"image": "/ilustracoes/marta-e-maria/quadros/faixa-4-6-1.webp", "speech": "Seja bem-vindo!", "caption": "Jesus chegou à casa de Marta, e ela o recebeu."}, {"image": "/ilustracoes/marta-e-maria/quadros/faixa-4-6-2.webp", "speech": "Quero ouvir você.", "caption": "Marta cuidava de tudo. Maria se sentou aos pés de Jesus para ouvir."}, {"image": "/ilustracoes/marta-e-maria/quadros/faixa-4-6-3.webp", "caption": "Marta ficou cansada de tanto trabalhar.", "speech": "Tem tanta coisa para fazer!"}, {"image": "/ilustracoes/marta-e-maria/quadros/faixa-4-6-4.webp", "speech": "Marta, Marta...", "caption": "Marta pediu ajuda. Jesus disse que Maria tinha feito uma boa escolha e podia ficar ali."}]'::jsonb), updated_at = now() WHERE devotional_id = 'cmvyv3ozp003ho72lezbf5h9r' AND band = '4-6' AND language = 'pt-BR' AND jsonb_array_length(story->'panels') = 3;
UPDATE devotional_kids SET story = jsonb_set(story, '{panels}', '[{"image": "/ilustracoes/marta-e-maria/quadros/faixa-4-6-1.webp", "speech": "Welcome!", "caption": "Jesus came to Martha''s house, and she welcomed him."}, {"image": "/ilustracoes/marta-e-maria/quadros/faixa-4-6-2.webp", "speech": "I want to hear you.", "caption": "Martha took care of everything. Mary sat at Jesus'' feet to listen."}, {"image": "/ilustracoes/marta-e-maria/quadros/faixa-4-6-3.webp", "caption": "Martha got tired from working so much.", "speech": "There is so much to do!"}, {"image": "/ilustracoes/marta-e-maria/quadros/faixa-4-6-4.webp", "speech": "Martha, Martha...", "caption": "Martha asked for help. Jesus said Mary had made a good choice and could stay."}]'::jsonb), updated_at = now() WHERE devotional_id = 'cmvyv3ozp003ho72lezbf5h9r' AND band = '4-6' AND language = 'en' AND jsonb_array_length(story->'panels') = 3;
UPDATE devotional_kids SET story = jsonb_set(story, '{panels}', '[{"image": "/ilustracoes/marta-e-maria/quadros/faixa-4-6-1.webp", "speech": "¡Bienvenido!", "caption": "Jesús llegó a la casa de Marta, y ella lo recibió."}, {"image": "/ilustracoes/marta-e-maria/quadros/faixa-4-6-2.webp", "speech": "Quiero escucharte.", "caption": "Marta se ocupaba de todo. María se sentó a los pies de Jesús para escuchar."}, {"image": "/ilustracoes/marta-e-maria/quadros/faixa-4-6-3.webp", "caption": "Marta se cansó de tanto trabajar.", "speech": "¡Hay tanto por hacer!"}, {"image": "/ilustracoes/marta-e-maria/quadros/faixa-4-6-4.webp", "speech": "Marta, Marta...", "caption": "Marta pidió ayuda. Jesús dijo que María había hecho una buena elección y podía quedarse."}]'::jsonb), updated_at = now() WHERE devotional_id = 'cmvyv3ozp003ho72lezbf5h9r' AND band = '4-6' AND language = 'es' AND jsonb_array_length(story->'panels') = 3;
UPDATE devotional_kids SET story = jsonb_set(story, '{panels}', '[{"image": "/ilustracoes/marta-e-maria/quadros/faixa-4-6-1.webp", "speech": "Sois le bienvenu !", "caption": "Jésus est arrivé chez Marthe, et elle l''a accueilli."}, {"image": "/ilustracoes/marta-e-maria/quadros/faixa-4-6-2.webp", "speech": "Je veux t''écouter.", "caption": "Marthe s''occupait de tout. Marie s''est assise aux pieds de Jésus pour écouter."}, {"image": "/ilustracoes/marta-e-maria/quadros/faixa-4-6-3.webp", "caption": "Marthe était fatiguée de tant travailler.", "speech": "Il y a tant à faire !"}, {"image": "/ilustracoes/marta-e-maria/quadros/faixa-4-6-4.webp", "speech": "Marthe, Marthe...", "caption": "Marthe a demandé de l''aide. Jésus a dit que Marie avait fait un bon choix et qu''elle pouvait rester."}]'::jsonb), updated_at = now() WHERE devotional_id = 'cmvyv3ozp003ho72lezbf5h9r' AND band = '4-6' AND language = 'fr' AND jsonb_array_length(story->'panels') = 3;
UPDATE devotional_kids SET story = jsonb_set(story, '{panels}', '[{"image": "/ilustracoes/marta-e-maria/quadros/faixa-4-6-1.webp", "speech": "Benvenuto!", "caption": "Gesù arrivò a casa di Marta, e lei lo accolse."}, {"image": "/ilustracoes/marta-e-maria/quadros/faixa-4-6-2.webp", "speech": "Voglio ascoltarti.", "caption": "Marta si occupava di tutto. Maria si sedette ai piedi di Gesù per ascoltare."}, {"image": "/ilustracoes/marta-e-maria/quadros/faixa-4-6-3.webp", "caption": "Marta si stancò di lavorare tanto.", "speech": "C''è tanto da fare!"}, {"image": "/ilustracoes/marta-e-maria/quadros/faixa-4-6-4.webp", "speech": "Marta, Marta...", "caption": "Marta chiese aiuto. Gesù disse che Maria aveva fatto una buona scelta e poteva restare lì."}]'::jsonb), updated_at = now() WHERE devotional_id = 'cmvyv3ozp003ho72lezbf5h9r' AND band = '4-6' AND language = 'it' AND jsonb_array_length(story->'panels') = 3;
UPDATE devotional_kids SET story = jsonb_set(story, '{panels}', '[{"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/faixa-4-6-1.webp", "speech": "Quero agradecer a Jesus.", "caption": "Jesus comia na casa de Simão. Uma mulher chegou trazendo um frasco de perfume."}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/faixa-4-6-2.webp", "speech": "Obrigada, Jesus!", "caption": "Ela chorou, molhou os pés de Jesus com lágrimas e os enxugou com os cabelos."}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/faixa-4-6-3.webp", "caption": "Simão achou que a mulher não merecia estar ali. Jesus falou com ele com calma.", "speech": "Simão, tenho uma coisa para te dizer."}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/faixa-4-6-4.webp", "speech": "Que paz no coração!", "caption": "Jesus disse a ela que seus pecados estavam perdoados e que podia ir em paz."}]'::jsonb), updated_at = now() WHERE devotional_id = 'cmvyun7rw0032o72lmlzc68bk' AND band = '4-6' AND language = 'pt-BR' AND jsonb_array_length(story->'panels') = 3;
UPDATE devotional_kids SET story = jsonb_set(story, '{panels}', '[{"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/faixa-4-6-1.webp", "speech": "I want to thank Jesus.", "caption": "Jesus was eating at Simon''s house. A woman came in bringing a jar of perfume."}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/faixa-4-6-2.webp", "speech": "Thank you, Jesus!", "caption": "She cried, wet Jesus'' feet with her tears and dried them with her hair."}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/faixa-4-6-3.webp", "caption": "Simon thought the woman didn''t belong there. Jesus spoke to him calmly.", "speech": "Simon, I have something to tell you."}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/faixa-4-6-4.webp", "speech": "What peace in my heart!", "caption": "Jesus told her that her sins were forgiven and that she could go in peace."}]'::jsonb), updated_at = now() WHERE devotional_id = 'cmvyun7rw0032o72lmlzc68bk' AND band = '4-6' AND language = 'en' AND jsonb_array_length(story->'panels') = 3;
UPDATE devotional_kids SET story = jsonb_set(story, '{panels}', '[{"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/faixa-4-6-1.webp", "speech": "Quiero darle las gracias a Jesús.", "caption": "Jesús comía en casa de Simón. Una mujer llegó con un frasco de perfume."}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/faixa-4-6-2.webp", "speech": "¡Gracias, Jesús!", "caption": "Ella lloró, mojó los pies de Jesús con sus lágrimas y los secó con sus cabellos."}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/faixa-4-6-3.webp", "caption": "Simón pensó que la mujer no merecía estar allí. Jesús le habló con calma.", "speech": "Simón, tengo algo que decirte."}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/faixa-4-6-4.webp", "speech": "¡Qué paz en el corazón!", "caption": "Jesús le dijo que sus pecados estaban perdonados y que podía irse en paz."}]'::jsonb), updated_at = now() WHERE devotional_id = 'cmvyun7rw0032o72lmlzc68bk' AND band = '4-6' AND language = 'es' AND jsonb_array_length(story->'panels') = 3;
UPDATE devotional_kids SET story = jsonb_set(story, '{panels}', '[{"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/faixa-4-6-1.webp", "speech": "Je veux remercier Jésus.", "caption": "Jésus mangeait chez Simon. Une femme est arrivée avec un flacon de parfum."}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/faixa-4-6-2.webp", "speech": "Merci, Jésus !", "caption": "Elle a pleuré, mouillé les pieds de Jésus de ses larmes et les a essuyés avec ses cheveux."}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/faixa-4-6-3.webp", "caption": "Simon pensait que la femme n''avait pas sa place ici. Jésus lui parla calmement.", "speech": "Simon, j''ai quelque chose à te dire."}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/faixa-4-6-4.webp", "speech": "Quelle paix dans mon cœur !", "caption": "Jésus lui a dit que ses péchés étaient pardonnés et qu''elle pouvait partir en paix."}]'::jsonb), updated_at = now() WHERE devotional_id = 'cmvyun7rw0032o72lmlzc68bk' AND band = '4-6' AND language = 'fr' AND jsonb_array_length(story->'panels') = 3;
UPDATE devotional_kids SET story = jsonb_set(story, '{panels}', '[{"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/faixa-4-6-1.webp", "speech": "Voglio ringraziare Gesù.", "caption": "Gesù mangiava a casa di Simone. Una donna arrivò con un vasetto di profumo."}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/faixa-4-6-2.webp", "speech": "Grazie, Gesù!", "caption": "Lei pianse, bagnò i piedi di Gesù con le lacrime e li asciugò con i capelli."}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/faixa-4-6-3.webp", "caption": "Simone pensò che la donna non meritasse di stare lì. Gesù gli parlò con calma.", "speech": "Simone, ho una cosa da dirti."}, {"image": "/ilustracoes/a-mulher-e-o-perfume/quadros/faixa-4-6-4.webp", "speech": "Che pace nel cuore!", "caption": "Gesù le disse che i suoi peccati erano perdonati e che poteva andare in pace."}]'::jsonb), updated_at = now() WHERE devotional_id = 'cmvyun7rw0032o72lmlzc68bk' AND band = '4-6' AND language = 'it' AND jsonb_array_length(story->'panels') = 3;
UPDATE devotional_kids SET story = story || jsonb_build_object('images', '["/ilustracoes/reforma-protestante/quadros/faixa-11-13-1.webp", "/ilustracoes/reforma-protestante/quadros/faixa-11-13-2.webp", "/ilustracoes/reforma-protestante/quadros/faixa-11-13-3.webp", "/ilustracoes/reforma-protestante/quadros/faixa-11-13-4.webp"]'::jsonb), updated_at = now() WHERE devotional_id = 'cmvudrag10002oe2ldyzmvhaa' AND band = '11-13' AND language IN ('pt-BR','en','es','fr','it') AND story->>'format' = 'dilemma' AND NOT (story ? 'images');
UPDATE devotional_kids SET story = story || jsonb_build_object('images', '["/ilustracoes/davi-e-a-arca/quadros/faixa-11-13-1.webp", "/ilustracoes/davi-e-a-arca/quadros/faixa-11-13-2.webp", "/ilustracoes/davi-e-a-arca/quadros/faixa-11-13-3.webp", "/ilustracoes/davi-e-a-arca/quadros/faixa-11-13-4.webp"]'::jsonb), updated_at = now() WHERE devotional_id = 'cmvue6llj000koe2lqtw0xdz2' AND band = '11-13' AND language IN ('pt-BR','en','es','fr','it') AND story->>'format' = 'dilemma' AND NOT (story ? 'images');
UPDATE devotional_kids SET story = story || jsonb_build_object('images', '["/ilustracoes/levi-e-o-banquete/quadros/faixa-11-13-1.webp", "/ilustracoes/levi-e-o-banquete/quadros/faixa-11-13-2.webp", "/ilustracoes/levi-e-o-banquete/quadros/faixa-11-13-3.webp", "/ilustracoes/levi-e-o-banquete/quadros/faixa-11-13-4.webp"]'::jsonb), updated_at = now() WHERE devotional_id = 'cmvv1whpq0002pm2l3f1bfo13' AND band = '11-13' AND language IN ('pt-BR','en','es','fr','it') AND story->>'format' = 'dilemma' AND NOT (story ? 'images');
UPDATE devotional_kids SET story = story || jsonb_build_object('images', '["/ilustracoes/a-mulher-e-o-perfume/quadros/faixa-11-13-1.webp", "/ilustracoes/a-mulher-e-o-perfume/quadros/faixa-11-13-2.webp", "/ilustracoes/a-mulher-e-o-perfume/quadros/faixa-11-13-3.webp", "/ilustracoes/a-mulher-e-o-perfume/quadros/faixa-11-13-4.webp"]'::jsonb), updated_at = now() WHERE devotional_id = 'cmvyun7rw0032o72lmlzc68bk' AND band = '11-13' AND language IN ('pt-BR','en','es','fr','it') AND story->>'format' = 'dilemma' AND NOT (story ? 'images');
UPDATE devotional_kids SET story = story || jsonb_build_object('images', '["/ilustracoes/marta-e-maria/quadros/faixa-11-13-1.webp", "/ilustracoes/marta-e-maria/quadros/faixa-11-13-2.webp", "/ilustracoes/marta-e-maria/quadros/faixa-11-13-3.webp", "/ilustracoes/marta-e-maria/quadros/faixa-11-13-4.webp"]'::jsonb), updated_at = now() WHERE devotional_id = 'cmvyv3ozp003ho72lezbf5h9r' AND band = '11-13' AND language IN ('pt-BR','en','es','fr','it') AND story->>'format' = 'dilemma' AND NOT (story ? 'images');
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM devotional_kids WHERE devotional_id IN ('cmvudrag10002oe2ldyzmvhaa','cmvue6llj000koe2lqtw0xdz2','cmvv1whpq0002pm2l3f1bfo13','cmvyun7rw0032o72lmlzc68bk','cmvyv3ozp003ho72lezbf5h9r') AND band IN ('4-6','7-10') AND language IN ('pt-BR','en','es','fr','it') AND (SELECT count(DISTINCT p->>'image') FROM jsonb_array_elements(story->'panels') p) < 4;
  IF n <> 0 THEN RAISE EXCEPTION '% versoes 4-6 ou 7-10 sem as 4 imagens', n; END IF;
  SELECT count(*) INTO n FROM devotional_kids WHERE devotional_id IN ('cmvudrag10002oe2ldyzmvhaa','cmvue6llj000koe2lqtw0xdz2','cmvv1whpq0002pm2l3f1bfo13','cmvyun7rw0032o72lmlzc68bk','cmvyv3ozp003ho72lezbf5h9r') AND band = '11-13' AND language IN ('pt-BR','en','es','fr','it') AND jsonb_array_length(story->'images') <> 4;
  IF n <> 0 THEN RAISE EXCEPTION '% dilemas sem as 4 imagens', n; END IF;
END $$;
SELECT band, count(*) AS versoes FROM devotional_kids WHERE devotional_id IN ('cmvudrag10002oe2ldyzmvhaa','cmvue6llj000koe2lqtw0xdz2','cmvv1whpq0002pm2l3f1bfo13','cmvyun7rw0032o72lmlzc68bk','cmvyv3ozp003ho72lezbf5h9r') AND band IN ('4-6','7-10','11-13') GROUP BY 1 ORDER BY 1;
COMMIT;
